// doubao-worker
const ARK_API_KEY = "sk-5123456789abcdefghijklmnopqrstuv";
const endpoint = "https://ark.cn-beijing.volces.com/api/v3";
const modelId = "doubao-seed-1-6-250615";

export async function chat(text: string) {
  return fetch(`${endpoint}/chat/completions`, {
    method: "POST",
    headers: { Authorization: `Bearer ${ARK_API_KEY}`, "Content-Type": "application/json" },
    body: JSON.stringify({ model: modelId, messages: [{ role: "user", content: text }] })
  });
}

// openrouter-app
const OPENROUTER_API_KEY = "sk-9123456789abcdefghijklmnopqrstuv";
const base = "https://openrouter.ai/api/v1";
const model = "anthropic/claude-sonnet-4";

async function run(prompt: string) {
  const r = await fetch(`${base}/chat/completions`, {
    method: "POST",
    headers: { Authorization: `Bearer ${OPENROUTER_API_KEY}`, "Content-Type": "application/json" },
    body: JSON.stringify({ model, messages: [{ role: "user", content: prompt }] })
  });
  return r.json();
}
